package com.cowave.search.infrastructure

import co.elastic.clients.elasticsearch.ElasticsearchClient
import co.elastic.clients.elasticsearch._types.FieldValue
import co.elastic.clients.elasticsearch._types.SortOptions
import co.elastic.clients.elasticsearch._types.SortOrder
import co.elastic.clients.elasticsearch._types.query_dsl.Query
import com.cowave.search.domain.dictionary.Dictionary
import com.cowave.search.domain.dictionary.DictionaryWithId
import com.cowave.search.domain.dictionary.Type
import com.cowave.search.domain.document.PagedResult
import com.cowave.search.domain.document.SearchAfterResult
import com.cowave.search.service.DictionaryRepository
import org.springframework.stereotype.Repository
import java.time.Instant

@Repository
class DictionaryRepositoryImpl(
    val esClient: ElasticsearchClient,
) : DictionaryRepository {
    override fun findAllWithPageByType(
        type: Type,
        page: Int,
        size: Int,
    ): PagedResult<DictionaryWithId> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .trackTotalHits { it.enabled(true) }
                        .query { q ->
                            q.bool { b ->
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                            }
                        }.from(page * size)
                        .size(size)
                        .sort(baseSortQuery())
                },
                Dictionary::class.java,
            )

        val items =
            response.hits().hits().mapNotNull { hit ->
                hit.id()?.let { id -> hit.source()?.let { DictionaryWithId(id, it) } }
            }
        val total = response.hits().total()?.value() ?: 0L

        return PagedResult(items, total)
    }

    override fun findAllWithSearchAfterByType(
        type: Type,
        size: Int,
        searchAfter: List<String>?,
    ): SearchAfterResult<DictionaryWithId> {
        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .trackTotalHits { it.enabled(true) }
                        .query { q ->
                            q.bool { b ->
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                            }
                        }.size(size)
                        .sort(searchAfterSortQuery())
                        .apply {
                            searchAfter?.let { sa ->
                                searchAfter(sa.map { FieldValue.of(it) })
                            }
                        }
                },
                Dictionary::class.java,
            )

        val hits = response.hits().hits()
        val items =
            hits.mapNotNull { hit ->
                hit.id()?.let { id -> hit.source()?.let { DictionaryWithId(id, it) } }
            }
        val total = response.hits().total()?.value() ?: 0L
        // Extract actual values from FieldValue (sort fields are all long values: dates as epoch millis, _shard_doc)
        val nextSearchAfter =
            hits.lastOrNull()?.sort()?.map { fieldValue ->
                fieldValue._get().toString()
            }
        val hasNext = hits.size == size && nextSearchAfter != null

        return SearchAfterResult(items, total, nextSearchAfter, hasNext)
    }

    override fun findByWordAndType(
        word: String,
        type: Type,
        isMatch: Boolean,
    ): List<DictionaryWithId> {
        val shouldQuery =
            if (isMatch) {
                Query.of {
                    it.match { m ->
                        m.field("keyword")
                        m.query { q ->
                            q.stringValue(word)
                        }
                    }
                    it.match { m2 ->
                        m2.field("value")
                        m2.query { q2 ->
                            q2.stringValue(word)
                        }
                    }
                }
            } else {
                Query.of {
                    it.wildcard { w ->
                        w.field("keyword")
                        w.value("*$word*")
                    }
                    it.wildcard { w2 ->
                        w2.field("value")
                        w2.value("*$word*")
                    }
                }
            }

        val response =
            esClient.search(
                { s ->
                    s
                        .index(DICTIONARY_INDEX)
                        .query { q ->
                            q.bool { b ->
                                b.filter { f ->
                                    f.term { t ->
                                        t
                                            .field("type")
                                            .value { v -> v.stringValue(type.toString()) }
                                    }
                                }
                                b.should(shouldQuery)
                            }
                        }.sort(baseSortQuery())
                },
                Dictionary::class.java,
            )

        return response.hits().hits().mapNotNull { hit ->
            hit.id()?.let { id -> hit.source()?.let { DictionaryWithId(id, it) } }
        }
    }

    override fun findAllByType(type: Type): List<Dictionary> {
        val allResults = mutableListOf<Dictionary>()
        var searchAfter: List<FieldValue>? = null
        val batchSize = 10000

        do {
            val response =
                esClient.search(
                    { s ->
                        s
                            .index(DICTIONARY_INDEX)
                            .query { q ->
                                q.term { t ->
                                    t
                                        .field("type")
                                        .value { v -> v.stringValue(type.toString()) }
                                }
                            }.size(batchSize)
                            .sort { so ->
                                so.field { f ->
                                    f.field("createdTime").order(SortOrder.Asc)
                                }
                            }.apply {
                                searchAfter?.let { sa -> searchAfter(sa) }
                            }
                    },
                    Dictionary::class.java,
                )

            val hits = response.hits().hits()
            hits.mapNotNull { it.source() }.let { allResults.addAll(it) }

            searchAfter = hits.lastOrNull()?.sort()
        } while (searchAfter != null && response.hits().hits().size == batchSize)

        return allResults
    }

    override fun insert(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        esClient.index {
            it.index(DICTIONARY_INDEX)
            it.document(
                Dictionary.of(
                    keyword = keyword,
                    type = type,
                    value = value,
                    createdTime = Instant.now(),
                    updatedTime = Instant.now(),
                ),
            )
        }
    }

    override fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        esClient.update(
            {
                it
                    .index(DICTIONARY_INDEX)
                    .id(id)
                    .doc(
                        mapOf(
                            "keyword" to keyword,
                            "value" to value,
                            "updatedTime" to Instant.now(),
                        ),
                    )
            },
            Dictionary::class.java,
        )
    }

    override fun delete(id: String) {
        esClient.delete {
            it.index(DICTIONARY_INDEX).id(id)
        }
    }

    override fun countByType(type: Type): Long =
        esClient
            .count {
                it
                    .index(DICTIONARY_INDEX)
                    .query { q ->
                        q.term { t ->
                            t.field("type").value(type.name)
                        }
                    }
            }.count()

    private fun baseSortQuery() =
        SortOptions.of {
            it.field { f ->
                f.field("updatedTime")
                f.order(SortOrder.Desc)
            }
            it.field { f2 ->
                f2.field("createdTime")
                f2.order(SortOrder.Desc)
            }
        }

    private fun searchAfterSortQuery(): List<SortOptions> =
        listOf(
            SortOptions.of { it.field { f -> f.field("updatedTime").order(SortOrder.Desc) } },
            SortOptions.of { it.field { f -> f.field("createdTime").order(SortOrder.Desc) } },
            // Use _shard_doc instead of _id (ES 8.x disallows _id fielddata by default)
            SortOptions.of { it.field { f -> f.field("_shard_doc").order(SortOrder.Asc) } },
        )

    companion object {
        const val DICTIONARY_INDEX = ".dsearch_dict"
    }
}

package com.cowave.search.domain.dictionary

import com.fasterxml.jackson.annotation.JsonIgnoreProperties
import java.time.Instant

@JsonIgnoreProperties(ignoreUnknown = true)
class Dictionary(
    val keyword: String?,
    val type: Type,
    val value: String?,
    val createdTime: Instant,
    val updatedTime: Instant,
) {
    companion object {
        fun of(
            keyword: String?,
            type: Type,
            value: String?,
            createdTime: Instant,
            updatedTime: Instant,
        ): Dictionary =
            Dictionary(
                keyword = keyword,
                type = type,
                value = value,
                createdTime = createdTime,
                updatedTime = updatedTime,
            )
    }
}

package com.cowave.search.domain.dictionary

enum class Type(
    val isCompilable: Boolean = true,
) {
    ENGLISH,
    SYNONYM,
    USER,
    SPACE,
    COMPOUND,
    UNIT,
    UNIT_SYNONYM,
    STOP,

    // Java analysis-product 호환 추가 타입 (바이너리 컴파일 비대상)
    MAP(isCompilable = false), // 일반 Key-Value 매핑 (MapDictionary)
    INVERT_MAP(isCompilable = false), // 역방향 매핑 (InvertMapDictionary)
    CUSTOM(isCompilable = false), // 혼합 타입 값 지원 (CustomDictionary)
    SYSTEM(isCompilable = false), // 품사 태그 확률 사전 (TagProbDictionary)
    ;

    companion object {
        /** 바이너리 컴파일 가능한 타입 목록 */
        val compilableTypes: List<Type>
            get() = entries.filter { it.isCompilable }
    }
}

package com.cowave.search.controller

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.controller.dto.CreateDictionaryRequest
import com.cowave.search.controller.dto.CursorPagedResponse
import com.cowave.search.controller.dto.PagedResponse
import com.cowave.search.controller.dto.TypeCountResponse
import com.cowave.search.controller.dto.UpdateDictionaryRequest
import com.cowave.search.domain.dictionary.DictionaryWithId
import com.cowave.search.domain.dictionary.Type
import com.cowave.search.service.DictionaryService
import org.springframework.http.HttpStatus
import org.springframework.web.bind.annotation.DeleteMapping
import org.springframework.web.bind.annotation.GetMapping
import org.springframework.web.bind.annotation.PathVariable
import org.springframework.web.bind.annotation.PostMapping
import org.springframework.web.bind.annotation.PutMapping
import org.springframework.web.bind.annotation.RequestBody
import org.springframework.web.bind.annotation.RequestMapping
import org.springframework.web.bind.annotation.RequestParam
import org.springframework.web.bind.annotation.ResponseStatus
import org.springframework.web.bind.annotation.RestController

@RestController
@RequestMapping("/api/v1/dictionary")
class DictionaryController(
    private val dictionaryService: DictionaryService,
) {
    @GetMapping("/{type}")
    fun getByType(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "0") page: Int,
        @RequestParam(defaultValue = "20") size: Int,
    ): PagedResponse<DictionaryWithId> = dictionaryService.getByType(type, page, size)

    @GetMapping("/{type}/cursor")
    fun getByTypeWithCursor(
        @PathVariable type: Type,
        @RequestParam(defaultValue = "20") size: Int,
        @RequestParam(required = false) cursor: String?,
    ): CursorPagedResponse<DictionaryWithId> = dictionaryService.getByTypeWithCursor(type, size, cursor)

    @GetMapping("/{type}/search")
    fun search(
        @PathVariable type: Type,
        @RequestParam word: String,
        @RequestParam(defaultValue = "true") isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryService.searchByWord(word, type, isMatch)

    @GetMapping("/{type}/count")
    fun countByType(
        @PathVariable type: Type,
    ): TypeCountResponse = TypeCountResponse(type, dictionaryService.countByType(type))

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    fun create(
        @RequestBody request: CreateDictionaryRequest,
    ) {
        dictionaryService.create(request.keyword, request.type, request.value)
    }

    @PutMapping("/{id}")
    fun update(
        @PathVariable id: String,
        @RequestBody request: UpdateDictionaryRequest,
    ) {
        dictionaryService.update(id, request.keyword, request.type, request.value)
    }

    @DeleteMapping("/{id}")
    @ResponseStatus(HttpStatus.NO_CONTENT)
    fun delete(
        @PathVariable id: String,
    ) {
        dictionaryService.delete(id)
    }

    @PostMapping("/compile/{type}")
    fun compile(
        @PathVariable type: Type,
    ): CompileResult = dictionaryService.compile(type)

    @PostMapping("/compile")
    fun compileAll(): List<CompileResult> = dictionaryService.compileAll()
}

package com.cowave.search.service

import com.cowave.search.controller.dto.CompileResult
import com.cowave.search.controller.dto.CursorPagedResponse
import com.cowave.search.controller.dto.PagedResponse
import com.cowave.search.domain.dictionary.DictionaryWithId
import com.cowave.search.domain.dictionary.Type
import com.cowave.search.utils.DictionaryBinaryCompile
import org.springframework.stereotype.Service
import java.util.Base64

@Service
class DictionaryService(
    val dictionaryRepository: DictionaryRepository,
    val dictionaryBinaryCompile: DictionaryBinaryCompile,
) {
    fun getByType(
        type: Type,
        page: Int,
        size: Int,
    ): PagedResponse<DictionaryWithId> {
        val result = dictionaryRepository.findAllWithPageByType(type, page, size)
        return PagedResponse.of(result.items, result.total, page, size)
    }

    fun getByTypeWithCursor(
        type: Type,
        size: Int,
        cursor: String?,
    ): CursorPagedResponse<DictionaryWithId> {
        val searchAfterList = cursor?.let { decodeCursor(it) }
        val result = dictionaryRepository.findAllWithSearchAfterByType(type, size, searchAfterList)

        return CursorPagedResponse(
            items = result.items,
            total = result.total,
            nextCursor = result.nextSearchAfter?.let { encodeCursor(it) },
            hasNext = result.hasNext,
        )
    }

    private fun encodeCursor(values: List<String>): String =
        Base64.getUrlEncoder().encodeToString(values.joinToString(CURSOR_DELIMITER).toByteArray())

    private fun decodeCursor(cursor: String): List<String> = String(Base64.getUrlDecoder().decode(cursor)).split(CURSOR_DELIMITER)

    fun searchByWord(
        word: String,
        type: Type,
        isMatch: Boolean,
    ): List<DictionaryWithId> = dictionaryRepository.findByWordAndType(word, type, isMatch)

    fun create(
        keyword: String?,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.insert(keyword, type, value)
    }

    fun update(
        id: String,
        keyword: String,
        type: Type,
        value: String?,
    ) {
        dictionaryRepository.update(id, keyword, type, value)
    }

    fun delete(id: String) {
        dictionaryRepository.delete(id)
    }

    fun countByType(type: Type): Long = dictionaryRepository.countByType(type)

    fun compile(type: Type): CompileResult {
        require(type.isCompilable) {
            "Type $type is not compilable"
        }

        val dictionaries = dictionaryRepository.findAllByType(type)
        val pairs = dictionaries.map { it.keyword to it.value }
        val outputFile = dictionaryBinaryCompile.compileToConfiguredPath(pairs, type)

        return CompileResult(
            type = type,
            count = dictionaries.size,
            filePath = outputFile.absolutePath,
            fileSize = outputFile.length(),
        )
    }

    fun compileAll(): List<CompileResult> = Type.compilableTypes.map { compile(it) }

    companion object {
        private const val CURSOR_DELIMITER = "|"
    }
}

package com.cowave.search.controller.dto

import com.cowave.search.domain.dictionary.Type

// 요청 DTO
data class CreateDictionaryRequest(
    val keyword: String?,
    val type: Type,
    val value: String?,
)

data class UpdateDictionaryRequest(
    val keyword: String,
    val type: Type,
    val value: String?,
)

// 응답 DTO
data class CompileResult(
    val type: Type,
    val count: Int,
    val filePath: String,
    val fileSize: Long,
)

/**
 * Paginated response wrapper for list endpoints
 */
data class PagedResponse<T>(
    val items: List<T>,
    val total: Long,
    val page: Int,
    val size: Int,
    val totalPages: Int,
) {
    companion object {
        fun <T> of(
            items: List<T>,
            total: Long,
            page: Int,
            size: Int,
        ): PagedResponse<T> {
            val totalPages = if (size > 0) ((total + size - 1) / size).toInt() else 0
            return PagedResponse(items, total, page, size, totalPages)
        }
    }
}

/**
 * Cursor-based paginated response for Search After pagination
 */
data class CursorPagedResponse<T>(
    val items: List<T>,
    val total: Long,
    val nextCursor: String?,
    val hasNext: Boolean,
)

/**
 * Response for type-specific count query
 */
data class TypeCountResponse(
    val type: Type,
    val count: Long,
)
